/**
 * File bytes kept inside PostgreSQL, for hosts with no persistent disk (e.g. a free Render web service wipes its
 * disk on every restart). Same three functions as storage/local.js.
 *
 * Each call opens its own transaction scoped to the institute named in the key ("<tenantId>/<uuid>", generated by us,
 * never from user input). That matters for downloads: the controller commits the request's transaction BEFORE reading
 * the bytes, so a read that relied on the request's transaction would find nothing.
 */
import { q, withTx } from '../db/pool.js';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const tenantOf = (key) => {
  const t = String(key).split('/')[0];
  if (!UUID_RE.test(t) || !/^[0-9a-f-]{36}\/[0-9a-f-]{36}$/i.test(String(key))) throw new Error('Invalid storage key');
  return t;
};

export async function put(key, buffer) {
  await withTx({ tenantId: tenantOf(key) }, () => q('insert into file_blobs (storage_key, data) values ($1, $2)', [key, buffer]));
}

export async function get(key) {
  const { rows } = await withTx({ tenantId: tenantOf(key) }, () => q('select data from file_blobs where storage_key = $1', [key]));
  if (!rows[0]) throw Object.assign(new Error('Stored file not found'), { code: 'ENOENT' });
  return rows[0].data;
}

export const remove = async (key) => { await withTx({ tenantId: tenantOf(key) }, () => q('delete from file_blobs where storage_key = $1', [key])); };
